head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
// 
// ********************************************************************

scwin.gReqAcptNo;
scwin.gAnsRnd;
scwin.gIsurCd;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gParamObj = new Array(1);
scwin.vScrenID = 'ULDSTF30203.xml';X < !정보--;
셋팅-- > function() {
    scwin.gEmpNo = js_emp_no; // 세션정보 

    scwin.gReqAcptNo = $c.frame.path("../").scwin.gReqAcptNo;
    scwin.gAnsRnd = $c.frame.path("../").scwin.gAnsRnd;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    //alert("자식창:"+gAcptNo+","+ gIsurCd);

    txb_com_abbrv.setValue($c.frame.path("../").txb_com_abbrv.getValue());
    txb_emp_nm.setValue(js_emp_nm);
};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Insert = function() {
    var vDeadlineDd = $c.stf.getObjectValue(edt_deadline_dd);
    if (vDeadlineDd.length < 8) {
        $c.win.alert("날짜를 올바르게 입력하시오.");
        edt_deadline_dd.focus();
        return;
    }
    var vAnsAcptNo = $c.stf.getObjectValue(txb_acptno);
    if (vAnsAcptNo.length != 14) {
        $c.win.alert("답변공시를 선택하여 올바르게 입력하시오.");
        return;
    }
    dts_inquiry.insertRow();
    dts_inquiry.setCellData(1, "REQ_ACPT_NO", scwin.gReqAcptNo);
    dts_inquiry.setCellData(1, "ANS_ACPT_NO", $c.stf.getObjectValue(txb_acptno));
    dts_inquiry.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_inquiry.setCellData(1, "ADM_DEADLINE", vDeadlineDd);
    dts_inquiry.setCellData(1, "FINAL_YN", $c.stf.getObjectValue(cmb_final_yn));
    dts_inquiry.setCellData(1, "REMK", $c.stf.getObjectValue(txa_remk));
    //alert(dts_nfaith.text);

    var vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer == true) {
        //alert(dts_again.text);
        trs_inquiry.Action = "/InquiryDisclosure.do?method=registerInquiryDsclAns&inputMessageId=INQDISCLSANS_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_inquiry.KeyName = "toinb_dataid4";
        trs_inquiry.KeyValue = "JSP(I:pInput=dts_inquiry)";
        trs_inquiry.Post();
    }
};
scwin.img_cls_dd_onclick = function() {
    popUpCalendar2(edt_deadline_dd);
};
scwin.img_search_onclick = async function() {
    var winTitle = txb_com_abbrv.getValue() + " / 수시공시 제출현황";
    var url = "/dsclmgt/ULDSTF30204.gfm";
    await $c.frame.CreateFrame("DSCLLIST" + scwin.gIsurCd, url, winTitle, 70, 10, 630, 330 + 30, "window", 0, 0, true);
    /*
    var url = "/dsclmgt/ULDSTF30204.gfm?";
    	url += "&ISUR_CD=" + gIsurCd;
    	url += "&frameID=" + frame.FrameID;
    //frame.Provider("/top").GWinOpen("child01", url, winTitle, 100, 20, 790, 460+30,"");
    //frame.Provider("/top").WinOpen("DSCLLIST"+gIsurCd,  url, winTitle, 790, 460+30);
    */

};
scwin.trs_inquiry_OnSuccess = async function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    await $c.frame.CloseFrame();
    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_Search();
};
scwin.trs_inquiry_OnFail = function() {
    $c.win.alert('trs_inquiry.OnFail() :' + trs_inquiry.ErrorMsg);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Insert();
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);

    //hidden 추가 (ysh)
    $c.stf.showObj(txb_acptno, false);
    fn_GetParentValue();

    // 가우스헤더 셋팅
    dts_inquiry.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=INQDISCLSANS_INOUT";
    dts_inquiry.reset();
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_01);
};
